module traffic_light(
    input rst_n, input clk, input pass_request,
    output [7:0] clock,
    output red, yellow, green
);
    // TODO: Your implementation
    // Parameter declaration
    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    // Reg declaration
    reg [1:0] state;
    reg [1:0] n_state;
    reg [7:0] cnt;
    wire [7:0] cnt_next;
    reg p_red, p_yellow, p_green;
    // Combinational logic
    assign cnt_next = cnt > 8'h0 ? cnt - 8'h1 : 8'h0;
    always @(*) begin
        case(state)
            idle: n_state <= s1_red;
            s1_red: n_state <= (cnt == 8'h3 || pass_request && p_green)? s3_green : s1_red;
            s2_yellow: n_state <= (cnt == 8'h3)? s1_red : s2_yellow;
            s3_green: n_state <= (cnt == 8'h3)? s2_yellow : s3_green;
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 8'd10;
            state <= idle;

            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            cnt <= cnt_next;
            state <= n_state;

            p_red <= (state != s1_red);
            p_yellow <= (state != s2_yellow);
            p_green <= (state != s3_green);
        end
    end
    // Assign statement
    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
endmodule
